718	    //    kIL is CAPPED (kDecMaxIL=2) so the register/smem cost is bounded regardless
719	    //    of m_atoms (the dW micro-gate runs Nout=512 → 8 atoms; an 8-wide interleave
720	    //    would need 8×64 accumulator regs). Groups reuse the SAME ring slots
721	    //    sequentially (like the old atom loop). Per-atom accumulation stays
722	    //    ASCENDING-k (k=0 overwrite, k>0 add) → numerics bit-identical + A/A/A
723	    //    determinism UNCHANGED. Ring stages kIL A-tiles (slot sl, atom-in-group ai at
724	    //    +ai·kDecTcSmemA1) + ONE shared B-tile; smem{A} must hold kIL·kDecTcStages
725	    //    tiles (DecTcSmem sizes it for kAtomsM=production max).
726	    constexpr int kIL = (MaxAtomsM < kDecMaxIL) ? MaxAtomsM : kDecMaxIL;
727	    wgs::WgmmaAccum<N> acc[kIL];                 // kIL live fragments per group
728	
729	    // Stage k-tile for a group of `g_atoms` (<= kIL) atoms based at `gbase`: the
730	    // g_atoms A-tiles (rows gbase+ai·64) + the shared B-tile, into ring slot k % S.
731	    auto stage_k = [&] (int gbase, int g_atoms, int k) {
732	        const int sl = k % S;
733	        for (int ai = 0; ai < g_atoms; ++ai) {
734	            const int mbase = gbase + ai * wgs::kWgmmaAtomM;
735	            stage_kmajor_tile<wgs::kWgmmaAtomM>(
736	                smemA + ((int64_t)sl * kIL + ai) * kDecTcSmemA1, k * wgs::kWgmmaAtomK,
737	                [&] (int mn, int kk) { return srcA(mbase + mn, kk); }, tid, nthreads);
738	        }
739	        stage_kmajor_tile<N>(
740	            smemB + (int64_t)sl * kDecTcSmemB1, k * wgs::kWgmmaAtomK,
741	            [&] (int mn, int kk) { return srcB(mn, kk); }, tid, nthreads);
742	    };
743	    // Issue the group's g_atoms wgmmas for staged slot k (k=0 overwrite else accum).
744	    // `rs` is the ring-slot modulus (kDecTcStages for the scalar/dW path; the
745	    // deeper kDecFwdStages for the fwd/dX cp.async ring). Both are compile-time at
746	    // every call site so the % folds; the wgmma ISSUE SEQUENCE (ascending k, k=0
747	    // overwrite / k>0 accumulate) is identical regardless of rs — only the slot
748	    // the operands were staged into differs, so the fp32 accumulation order is
749	    // bit-identical (parity / A/A/A preserved).
750	    auto issue_k = [&] (int g_atoms, int k, int rs) {
751	        const int sl = k % rs;
752	        wgs::SmemDesc dB = wgs::make_desc_B_kmajor<N, wgs::kSwizzleNone>(
753	            smemB + (int64_t)sl * kDecTcSmemB1);
754	        #pragma unroll
755	        for (int ai = 0; ai < kIL; ++ai) {
756	            if (ai >= g_atoms) break;
757	            wgs::SmemDesc dA = wgs::make_desc_A_kmajor<wgs::kWgmmaAtomM, wgs::kSwizzleNone>(
758	                smemA + ((int64_t)sl * kIL + ai) * kDecTcSmemA1);
759	            if (k == 0) wgs::wgmma_m64nNk16_bf16<N, /*ScaleD=*/0, 0, 0>(acc[ai], dA, dB);
760	            else        wgs::wgmma_m64nNk16_bf16<N, /*ScaleD=*/1, 0, 0>(acc[ai], dA, dB);
761	        }
762	    };
763	
764	    // ── cp.async DOUBLE-BUFFERED RING (campaign RING; unblocked by C1/C1-T).
765	    //    Selected at COMPILE TIME when BOTH sources are flat-gmem K-major rows
766	    //    (DecGmemTileSrc*, i.e. the fwd/dX wrappers) and the ring has >= 2 slots.
767	    //    Same slot ring, same ascending-k issue order, same __syncthreads
768	    //    choreography as the synchronous path — ONLY the staging TRANSPORT
769	    //    changes: the per-element 2-byte LDG→reg→STS loop (≈16 dependent
770	    //    load/store pairs per thread per k-tile, latency exposed in register-
771	    //    window-limited chunks) becomes 2 fire-and-forget 16-byte
772	    //    cp.async.cg copies per thread (LDGSTS: gmem→smem direct, no register
773	    //    round-trip, the WHOLE tile in flight at once) issued while wg0's
774	    //    wgmmas on the PREVIOUS tile execute in the tensor pipe. The
775	    //    per-thread cp_async_wait_group<0> + ONE fence.proxy.async + the
776	    //    existing __syncthreads publish the slot before its first wgmma — the
777	    //    primitives.cuh contract (issue→commit→wait→barrier→read), i.e. the
778	    //    silicon-validated tile_pipeline handshake.
779	    //    NUMERICS: identical bytes land in identical smem offsets in the same
780	    //    k-order; the wgmma sequence is untouched → results bit-identical to
781	    //    the synchronous staging (fp64-oracle parity / A/A/A by construction).
782	    //    dW keeps the synchronous staging (lambda sources: transposed-strided
783	    //    acts reads = ring blocker (b), needs TMA-with-transpose; out of scope).
784	    constexpr bool kRingAsync = (S > 1)
785	        && DecTileSrcIsGmem<SrcA>::value && DecTileSrcIsGmem<SrcB>::value;
786	
787	    // ── FINE-profiler accumulators (SG_DEC_PROFILE && SG_DEC_PROFILE_FWD_FINE).
788	    //    Thread-0-only clock64 deltas, summed across ALL M-atom groups + k-steps
789	    //    of THIS engine call, atomicMax'd into g_dec_prof_fwd_fine ONCE after the
790	    //    group loop (= the slowest CTA's critical path per sub-phase). Compiled
791	    //    out entirely (no vars, no clock64, no atomic) unless the pair is set →
792	    //    byte-identical when off. Only the kRingAsync (fwd/dX) path stamps; the dW
793	    //    !kRingAsync path never reaches these TICs.
794	#if defined(SG_DEC_PROFILE) && SG_DEC_PROFILE_FWD_FINE
795	    unsigned long long _f_issue = 0, _f_wait = 0, _f_wgmma = 0, _f_epi = 0, _f_bar = 0;
796	    unsigned long long _t0 = 0;
797	    const bool _prof_t0 = (tid == 0);
798	    #define SG_FINE_TIC() do { if (_prof_t0) _t0 = clock64(); } while (0)
799	    #define SG_FINE_ACC(acc) do { if (_prof_t0) (acc) += clock64() - _t0; } while (0)
800	#else
801	    #define SG_FINE_TIC() do {} while (0)
802	    #define SG_FINE_ACC(acc) do {} while (0)
803	#endif
804	
805	    // Loop M-atom GROUPS of kIL; each group runs its own k-chain into kIL fragments.
806	    #pragma unroll 1
807	    for (int g0 = 0; g0 < m_atoms; g0 += kIL) {
808	        const int gbase = mbase0 + g0 * wgs::kWgmmaAtomM;
809	        const int g_atoms = (m_atoms - g0) < kIL ? (m_atoms - g0) : kIL;
810	        if constexpr (kRingAsync) {
811	            (void)stage_k;   // the scalar stager is the !ring branch's transport
812	            // RING DEPTH for the fwd/dX path. PIPE=0 → RS==kDecTcStages (the
813	            // shipped S=2 double-buffer), and the RS==2 sub-branch below is the
814	            // ORIGINAL ring VERBATIM → byte-identical PTX. PIPE=1 → RS=2..4 keeps
815	            // RS-1 cp.async groups in flight (deeper prefetch; the deeper sub-branch).
816	            constexpr int RS = kDecFwdStages;
817	            // Stage the group's k-tile `kk` into ring slot kk % RS via 16B cp.async:
818	            // g_atoms A(64×16) tiles + the ONE shared B(N×16) tile (the M-atom-
819	            // interleave structure, verbatim). Chunk space is FLAT and fixed
820	            // (kIL·64·2 A-halves then N·2 B-halves) so every thread's share is
821	            // static; halves of a dead atom (ai >= g_atoms) are skipped (their
822	            // smem is never read — issue_k stops at g_atoms). Each 16B half-row
823	            // (mn, k 8·half..8·half+7) lands at the canonical Major-K interleave
824	            // offset half·(MN·8)+mn·8 — the same map stage_kmajor_tile writes and
825	            // the same chunking tile_pipeline.cuh::pipeline_produce_ktile issues.
826	            auto stage_k_async = [&] (int kk) {
827	                const int sl = kk % RS;
828	                const int kb = kk * wgs::kWgmmaAtomK;
829	                constexpr int kAChunks = kIL * wgs::kWgmmaAtomM * 2;
830	                constexpr int kChunks  = kAChunks + N * 2;
831	                #pragma unroll 1
832	                for (int v = tid; v < kChunks; v += nthreads) {
833	                    if (v < kAChunks) {
834	                        const int ai = v / (wgs::kWgmmaAtomM * 2);
835	                        if (ai < g_atoms) {
836	                            const int r  = v - ai * (wgs::kWgmmaAtomM * 2);
837	                            const int mn = r >> 1, half = r & 1;
838	                            decprim::cp_async_cg_16(
839	                                smemA + ((int64_t)sl * kIL + ai) * kDecTcSmemA1
840	                                      + half * (wgs::kWgmmaAtomM * 8) + mn * 8,
841	                                srcA.chunk16(gbase + ai * wgs::kWgmmaAtomM + mn, kb, half));
842	                        }
843	                    } else {
844	                        const int r  = v - kAChunks;
845	                        const int mn = r >> 1, half = r & 1;
846	                        __nv_bfloat16* dst = smemB + (int64_t)sl * kDecTcSmemB1
847	                                           + half * (N * 8) + mn * 8;
848	                        if (srcB.row_valid(mn)) {
849	                            decprim::cp_async_cg_16(dst, srcB.chunk16(mn, kb, half));
850	                        } else {
851	                            // PAD row of a ragged N-tile: zero smem, NO gmem read
852	                            // (the epilogue drops pad cols; zeros keep them inert).
853	                            uint4 z; z.x = z.y = z.z = z.w = 0u;
854	                            *reinterpret_cast<uint4*>(dst) = z;
855	                        }
856	                    }
857	                }
858	                decprim::cp_async_commit();
859	            };
860	            if constexpr (kDecFwdPipeEngine) {
861	                // ══════════════════════════════════════════════════════════════
862	                //  DESIGN-TOURNAMENT entry (b): PRODUCER/CONSUMER mbarrier ENGINE
863	                //  (SG_TUNED_DEC_FWD_PIPE=2). The validated tile_pipeline.cuh
864	                //  choreography, transcribed here over the EXISTING ring tiles
865	                //  (smemA/smemB), the M-atom-interleave (acc[kIL]), and the
866	                //  bit-identical issue_k — so the only thing that changes vs the
867	                //  PIPE=0|1 ring is the THREAD SPLIT and the cross-warpgroup
868	                //  handoff: WG0 is the CONSUMER (wgmma into acc[]; owns the
869	                //  epilogue, like every other branch's `in_wg0`), WG1 is the
870	                //  PURE PRODUCER (cp.async-stages each k-tile + arrives `full`).
871	                //  The producer runs up to RS stages AHEAD of the consumer, gated
872	                //  only by the `empty` barrier, so the cp.async DRAIN is hidden
873	                //  behind the consumer's in-flight wgmmas (DRAIN-HIDING — the
874	                //  regime the fine profiler proved fwd/dX live in).
875	                //
876	                //  PARITY BY CONSTRUCTION: the consumer issues issue_k(g_atoms,k,RS)
877	                //  in ASCENDING k (k=0 overwrite / k>0 accumulate) into the SAME
878	                //  acc[ai] fragments as PIPE=0 — the wgmma ISSUE SEQUENCE and the
879	                //  fp32 accumulation order are bit-identical. The producer stages
880	                //  the SAME 16B chunks into the SAME canonical Major-K smem offsets
881	                //  the PIPE=0 stage_k_async writes; only WHEN a tile lands changes
882	                //  (a LOAD reorder). No ragged/atomic reduce: each acc[ai] is owned
883	                //  by one consumer thread, summed serially. dW/TP/selftest never
884	                //  reach here (!kRingAsync). Identical to the unpipelined kchain
885	                //  because the consumer issues the SAME ss-wgmma sequence in the
886	                //  SAME order (tile_pipeline.cuh DESIGN gate c).
887	                //
888	                //  Barriers: 2·RS words in pipeBars — full[0..RS) then empty[0..RS).
889	                //  Each expects a FULL WARPGROUP (128) of arrivals per phase (the
890	                //  tile_pipeline contract: a per-warp elect_one would give 4
891	                //  arrivals on a count-1 barrier and DEADLOCK the parity wait). The
892	                //  consumer arrives `empty` (releases a slot); the producer arrives
893	                //  `full` (publishes a slot) after its own cp_async_wait_group<0> +
894	                //  one fence.proxy.async (the portable wait_group handoff — the
895	                //  mbarrier is the cross-warpgroup ready SIGNAL, not the tx counter).
896	                auto bar_full  = [&] (int s) { return wgs::Mbarrier(pipeBars + s); };
897	                auto bar_empty = [&] (int s) { return wgs::Mbarrier(pipeBars + RS + s); };
898	                // Init the 2·RS barriers (thread 0), each expecting 128 arrivals.
899	                if (tid == 0) {
900	                    #pragma unroll
901	                    for (int s = 0; s < RS; ++s) { bar_full(s).init(128); bar_empty(s).init(128); }
902	                }
903	                __syncthreads();   // barriers initialized + visible before any arrive
904	
905	                // Producer-side stager: stage k-tile `kk` into slot kk%RS using ONLY
906	                // WG1's 128 threads (the producer warpgroup). SAME chunk math /
907	                // SAME canonical Major-K destination offsets as stage_k_async — only
908	                // the thread stride is the 128-wide producer group (tid_wg ∈ 0..127),
909	                // NOT all 256. (stage_k_async strides over 256 threads, so it is the
910	                // PIPE 0|1 transport; the producer/consumer split needs a 128-wide
911	                // producer.) Followed by cp_async_commit() (the caller drains+arrives).
912	                auto produce_ktile = [&] (int kk) {
913	                    const int sl = kk % RS;
914	                    const int kb = kk * wgs::kWgmmaAtomK;
915	                    constexpr int kAChunks = kIL * wgs::kWgmmaAtomM * 2;
916	                    constexpr int kChunks  = kAChunks + N * 2;
917	                    #pragma unroll 1
918	                    for (int v = tid_wg; v < kChunks; v += 128) {
919	                        if (v < kAChunks) {
920	                            const int ai = v / (wgs::kWgmmaAtomM * 2);
921	                            if (ai < g_atoms) {
922	                                const int r  = v - ai * (wgs::kWgmmaAtomM * 2);
923	                                const int mn = r >> 1, half = r & 1;
924	                                decprim::cp_async_cg_16(
925	                                    smemA + ((int64_t)sl * kIL + ai) * kDecTcSmemA1
926	                                          + half * (wgs::kWgmmaAtomM * 8) + mn * 8,
927	                                    srcA.chunk16(gbase + ai * wgs::kWgmmaAtomM + mn, kb, half));
928	                            }
929	                        } else {
930	                            const int r  = v - kAChunks;
931	                            const int mn = r >> 1, half = r & 1;
932	                            __nv_bfloat16* dst = smemB + (int64_t)sl * kDecTcSmemB1
933	                                               + half * (N * 8) + mn * 8;
934	                            if (srcB.row_valid(mn)) {
935	                                decprim::cp_async_cg_16(dst, srcB.chunk16(mn, kb, half));
936	                            } else {
937	                                uint4 z; z.x = z.y = z.z = z.w = 0u;
938	                                *reinterpret_cast<uint4*>(dst) = z;
939	                            }
940	                        }
941	                    }
942	                    decprim::cp_async_commit();
943	                };
944	
945	                if (!in_wg0) {
946	                    // ── PRODUCER (WG1): stage every k-tile in ascending k. With RS
947	                    //    buffering it runs up to RS stages ahead; for kk>=RS the slot
948	                    //    was used by kk-RS, so wait on `empty` before overwriting it
949	                    //    (WAR-safe: the consumer arrives empty only after wgmma kk-RS
950	                    //    drained). Each stage: produce → drain own cp.async →
951	                    //    fence.proxy.async → all-128-producer arrive `full`.
952	                    unsigned emptyp[RS];
953	                    #pragma unroll
954	                    for (int s = 0; s < RS; ++s) emptyp[s] = 0u;
955	                    #pragma unroll 1
956	                    for (int kk = 0; kk < k_steps; ++kk) {
957	                        const int sl = kk % RS;
958	                        if (kk >= RS) { bar_empty(sl).wait(emptyp[sl]); emptyp[sl] ^= 1u; }
959	                        SG_FINE_TIC(); produce_ktile(kk);                  SG_FINE_ACC(_f_issue);
960	                        SG_FINE_TIC(); decprim::cp_async_wait_group<0>();  SG_FINE_ACC(_f_wait);
961	                        wgs::fence_async_proxy();
962	                        bar_full(sl).arrive();   // publish slot sl (all 128 producers)
963	                    }
964	                } else {
965	                    // ── CONSUMER (WG0): wgmma over each staged k-tile in ascending k
966	                    //    into acc[] (k=0 overwrite / k>0 accumulate — bit-identical to
967	                    //    PIPE=0). Wait `full` before issuing, drain the wgmma, then
968	                    //    all-128-consumer arrive `empty` to release the slot. ONE
969	                    //    wgmma_fence before the chain (accumulators were just touched).
970	                    unsigned fullp[RS];
971	                    #pragma unroll
972	                    for (int s = 0; s < RS; ++s) fullp[s] = 0u;
973	                    wgs::wgmma_fence();
974	                    #pragma unroll 1
975	                    for (int k = 0; k < k_steps; ++k) {
976	                        const int sl = k % RS;
977	                        SG_FINE_TIC(); bar_full(sl).wait(fullp[sl]); fullp[sl] ^= 1u; SG_FINE_ACC(_f_wait);
978	                        SG_FINE_TIC();
979	                        issue_k(g_atoms, k, RS);
980	                        wgs::wgmma_commit_group();
981	                        wgs::wgmma_wait_group<0>();   // drain wgmma k → slot k%RS free
982	                        SG_FINE_ACC(_f_wgmma);
983	                        bar_empty(sl).arrive();       // release slot sl (all 128 consumers)
984	                    }
985	                }
986	                // The shared epilogue below stores acc[] from `in_wg0` = the CONSUMER
987	                // warpgroup (WG0 owns the fragments here), so it is correct as-is.
988	            } else if constexpr (RS <= 2) {
989	                // ── ORIGINAL S=2 DOUBLE-BUFFER RING (verbatim; byte-identical when
990	                //    PIPE=0). One prefetch tile in flight; full drain + barrier per k.
991	                //    (RS<=2 also covers the dead RS=1 case — kRingAsync needs S>1, so
992	                //    this block is only ever reached with RS>=2; the <=2 guard just
993	                //    keeps the deeper else-branch's cp_async_wait_group<RS-2> from
994	                //    being instantiated with a negative immediate.)
995	                // Prologue: tile 0 in flight → drain own copies → ONE async-proxy
996	                // fence → publish (barrier). Fence choreography then matches the
997	                // synchronous path (wgmma_fence once, wg0).
998	                SG_FINE_TIC(); stage_k_async(0);                 SG_FINE_ACC(_f_issue);
999	                SG_FINE_TIC(); decprim::cp_async_wait_group<0>(); SG_FINE_ACC(_f_wait);
1000	                SG_FINE_TIC(); wgs::fence_async_proxy(); __syncthreads(); SG_FINE_ACC(_f_bar);
1001	                if (in_wg0) wgs::wgmma_fence();
1002	                // Steady state: (1) wg0 issues the slot-k wgmmas (async tensor pipe);
1003	                // (2) ALL threads fire tile k+1's copies into the OTHER slot — the
1004	                // gmem→smem transfers overlap the in-flight wgmmas (slot (k+1)%2 was
1005	                // last READ by wgmma k-1, drained at the end of iteration k-1 →
1006	                // WAR-safe); (3) drain tensor pipe + own copies, fence, ONE barrier.
1007	                #pragma unroll 1
1008	                for (int k = 0; k < k_steps; ++k) {
1009	                    SG_FINE_TIC();
1010	                    if (in_wg0) { issue_k(g_atoms, k, RS); wgs::wgmma_commit_group(); }
1011	                    SG_FINE_ACC(_f_wgmma);
1012	                    SG_FINE_TIC(); if (k + 1 < k_steps) stage_k_async(k + 1); SG_FINE_ACC(_f_issue);
1013	                    SG_FINE_TIC(); if (in_wg0) wgs::wgmma_wait_group<0>();     SG_FINE_ACC(_f_wgmma);
1014	                    SG_FINE_TIC(); decprim::cp_async_wait_group<0>();          SG_FINE_ACC(_f_wait);
1015	                    SG_FINE_TIC(); wgs::fence_async_proxy(); __syncthreads();  SG_FINE_ACC(_f_bar);
1016	                }
1017	            } else {
1018	                // ── DEEPER cp.async RING (RS=3..4; SG_TUNED_DEC_FWD_PIPE=1). Keeps
1019	                //    RS-1 cp.async groups IN FLIGHT so more HBM operand latency is
1020	                //    hidden behind the in-flight wgmmas (the drain-bound lever).
1021	                //    PARITY: the wgmma ISSUE order is IDENTICAL to the RS==2 ring
1022	                //    (ascending k, per-k commit + wgmma_wait_group<0> drain) — only
1023	                //    the cp.async prefetch DISTANCE (and thus WHEN each tile lands)
1024	                //    changes. fp32 accumulation order bit-identical.
1025	                //
1026	                //    WAR safety: a refill for tile k+RS-1 writes slot (k+RS-1)%RS ==
1027	                //    (k-1)%RS, which tile k-1 occupied and wgmma k-1 finished reading
1028	                //    (drained via wgmma_wait_group<0> in iter k-1, ordered before this
1029	                //    iter's top __syncthreads). The refill goes to slot (k-1)%RS while
1030	                //    wgmma k reads slot k%RS (distinct) → no live-slot clobber.
1031	                //
1032	                //    FIFO drain discipline (cp_async_wait_group<N> is a compile-time
1033	                //    immediate, FIFO-ordered): in the STEADY region (a refill happens
1034	                //    this iter ⇒ exactly RS-1 groups in flight) wait_group<RS-2> drains
1035	                //    exactly the oldest (tile k). In the TAIL (refills exhausted) there
1036	                //    is no future copy to overlap, so wait_group<0> (drain all
1037	                //    remaining) is free and keeps the wait depth a valid immediate.
1038	                const int n_pre = (RS - 1) < k_steps ? (RS - 1) : k_steps;
1039	                #pragma unroll 1
1040	                for (int p = 0; p < n_pre; ++p) { SG_FINE_TIC(); stage_k_async(p); SG_FINE_ACC(_f_issue); }
1041	                if (in_wg0) wgs::wgmma_fence();
1042	                #pragma unroll 1
1043	                for (int k = 0; k < k_steps; ++k) {
1044	                    const bool will_refill = (k + (RS - 1) < k_steps);
1045	                    // Land tile k. Steady: keep RS-2 in flight. Tail: drain all.
1046	                    SG_FINE_TIC();
1047	                    if (will_refill) decprim::cp_async_wait_group<RS - 2>();
1048	                    else             decprim::cp_async_wait_group<0>();
1049	                    SG_FINE_ACC(_f_wait);
1050	                    SG_FINE_TIC(); wgs::fence_async_proxy(); __syncthreads(); SG_FINE_ACC(_f_bar);
1051	                    SG_FINE_TIC();
1052	                    if (in_wg0) {
1053	                        issue_k(g_atoms, k, RS);
1054	                        wgs::wgmma_commit_group();
1055	                        wgs::wgmma_wait_group<0>();   // drain wgmma k → slot k%RS free
1056	                    }
1057	                    SG_FINE_ACC(_f_wgmma);
1058	                    // Refill the ring (WAR-safe; see above). No post-wgmma barrier
1059	                    // needed: the refill targets slot (k-1)%RS, freed in iter k-1.
1060	                    SG_FINE_TIC(); if (will_refill) stage_k_async(k + (RS - 1)); SG_FINE_ACC(_f_issue);
1061	                }
1062	            }
1063	        } else {
1064	        // Prologue: stage tile 0 (the group's atoms); make visible; fence ONCE.
1065	        stage_k(gbase, g_atoms, 0);
1066	        __syncthreads();
1067	        if (in_wg0) wgs::wgmma_fence();
1068	        // Steady state (S=2 single group in flight): issue the g_atoms wgmmas for
1069	        // slot k%S (async, overlapping in the tensor pipe), THEN stage tile k+1 into
1070	        // the OTHER slot (HBM loads overlap the MMAs), THEN wait_group<0> + sync. S=1
1071	        // collapses to staging into the single slot AFTER the wait (serial, exact).
1072	        #pragma unroll 1
1073	        for (int k = 0; k < k_steps; ++k) {
1074	            if (in_wg0) { issue_k(g_atoms, k, S); wgs::wgmma_commit_group(); }
1075	            if (S > 1) {
1076	                if (k + 1 < k_steps) stage_k(gbase, g_atoms, k + 1);
1077	                if (in_wg0) wgs::wgmma_wait_group<0>();
1078	                __syncthreads();
1079	            } else {
1080	                if (in_wg0) wgs::wgmma_wait_group<0>();
1081	                __syncthreads();
1082	                if (k + 1 < k_steps) { stage_k(gbase, g_atoms, k + 1); __syncthreads(); }
1083	            }
1084	        }
1085	        }
1086	        // Epilogue: warpgroup 0 owns the fp32 fragments; decode + emit (real cols).
1087	        // All reads happen AFTER the final wait_group<0> — no overlap with any wgmma.
1088	        // EPI fine-stamp only on the ring (fwd/dX) path (constexpr-guarded so the dW
1089	        // !kRingAsync path emits no stamp); the store accessor cost is the EPI bucket.
1090	        if constexpr (kRingAsync) SG_FINE_TIC();
1091	        if (in_wg0) {
1092	            #pragma unroll
1093	            for (int ai = 0; ai < kIL; ++ai) {
1094	                if (ai >= g_atoms) break;
1095	                const int mbase = gbase + ai * wgs::kWgmmaAtomM;
1096	                #pragma unroll
1097	                for (int i = 0; i < wgs::WgmmaAccum<N>::kRegs; ++i) {
1098	                    int row, col;
1099	                    wgs::wgmma_frag_decode(tid_wg, i, N, row, col);
1100	                    if (col < n_real) out(mbase + row, col, acc[ai].c[i]);
1101	                }
1102	            }
1103	        }
1104	        if constexpr (kRingAsync) SG_FINE_ACC(_f_epi);
1105	        __syncthreads();
1106	    }
1107	    // Stamp the fine sub-phases ONCE (thread-0-only, atomicMax across CTAs). Only
1108	    // the ring (fwd/dX) path accumulated nonzero deltas (the dW path never TIC'd);
1109	    // guard on kRingAsync so the dW engine emits no atomic. prof_phase: 0 = fwd
1110	    // ring, 1 = dX ring (the wrapper passed it); -1 (defensive) → phase 0.
1111	#if defined(SG_DEC_PROFILE) && SG_DEC_PROFILE_FWD_FINE
1112	    if constexpr (kRingAsync) {
1113	        if (_prof_t0) {
1114	            const int ph = (prof_phase == 1) ? 1 : 0;
