1338	__device__ __forceinline__ DecTileScratch dec_tile_scratch_bind(float* slab) {
1339	    DecTileScratch s;
1340	    __nv_bfloat16* b = reinterpret_cast<__nv_bfloat16*>(slab);
1341	    int64_t bo = 0;
1342	    for (int li = 0; li < dec::kLayers; ++li) { s.qkv[li]    = b + bo; bo += (int64_t)kTileM * 3 * dec::kD; }
1343	    for (int li = 0; li < dec::kLayers; ++li) { s.ff0pre[li] = b + bo; bo += (int64_t)kTileM * dec::kDff; }
1344	    float* f = slab + (dec_tile_scratch_bf16_count() + 1) / 2;
1345	    int64_t fo = 0;
1346	    for (int li = 0; li < dec::kLayers; ++li) { s.attn[li] = f + fo; fo += kAttnPerTile; }
1347	    for (int li = 0; li < dec::kLayers; ++li) { s.n1x[li] = f + fo; fo += (int64_t)kTileM * dec::kD; s.n1i[li] = f + fo; fo += kTileM; }
1348	    for (int li = 0; li < dec::kLayers; ++li) { s.n2x[li] = f + fo; fo += (int64_t)kTileM * dec::kD; s.n2i[li] = f + fo; fo += kTileM; }
1349	    s.dsc  = f + fo; fo += kAttnPerTile;
1350	    s.fnx  = f + fo; fo += (int64_t)kTileM * dec::kD;
1351	    s.fni  = f + fo; fo += kTileM;
1352	    s.dh   = f + fo; fo += (int64_t)kTileM * dec::kD;
1353	    s.x1   = f + fo; fo += (int64_t)kTileM * dec::kD;
1354	    s.finalin = f + fo; fo += (int64_t)kTileM * dec::kD;
1355	    s.logits  = f + fo; fo += kLogitsPerTile;
1356	    s.work    = f + fo; fo += (int64_t)kTileM * dec::kDff;
1357	    s.work2   = f + fo; fo += (int64_t)kTileM * dec::kDff;
1358	    return s;
1359	}
