2011	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
2012	//
2013	// When SG_TUNED_DEC_DW_STAGE==1, `dwt_base` is the contiguous bf16 transpose
2014	// scratch (dec_dw_transpose_elems sized) and each spec's dYt/Xt/t_off are bound
2015	// to its packed sub-block (same running-offset walk as dec_dw_transpose_elems +
2016	// the host carve). On the scalar path pass dwt_base=nullptr → dYt/Xt stay null.
2017	__device__ __forceinline__ void dectc_build_dw_specs(
2018	        const DecActs& acts, int B, int T, DecDwSpec spec[9],
2019	        __nv_bfloat16* dwt_base);
2020	
2021	// Back-compat overload (scalar path / pre-existing call sites): no transpose
2022	// scratch. Forwards with dwt_base=nullptr so dYt/Xt are null and stage==0 runs
2023	// the proven lambda gather unchanged.
2024	__device__ __forceinline__ void dectc_build_dw_specs(
2025	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
2026	    dectc_build_dw_specs(acts, B, T, spec, /*dwt_base=*/nullptr);
2027	}
2028	
2029	__device__ __forceinline__ void dectc_build_dw_specs(
2030	        const DecActs& acts, int B, int T, DecDwSpec spec[9],
2031	        __nv_bfloat16* dwt_base) {
2032	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
2033	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
2034	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
2035	    //   head: out_w=28 (out_b=29)
2036	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
2037	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
2038	    for (int s = 0; s < 8; ++s) {
2039	        const int li = s / 4, kind = s % 4;
2040	        DecDwSpec& sp = spec[s];
2041	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
2042	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
2043	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
2044	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
2045	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
2046	        sp.dY_bias = sp.dY;
2047	    }
2048	    DecDwSpec& hd = spec[8];
2049	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
2050	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
2051	
2052	    // CONTIGUOUS-TRANSPOSE bind (stage==1): pack each weight's dYt[Mpad,K] then
2053	    // Xt[Kin,K] into dwt_base via the SAME running-offset walk dec_dw_transpose_elems
2054	    // uses (so the kernel offsets == the host carve). On the scalar path (dwt_base
2055	    // null / stage==0) leave dYt/Xt null → dectc_dw_run_tile takes the lambda gather.
2056	    // #if-guarded (not if-constexpr): the dYt/Xt/t_off fields only EXIST when the
2057	    // macro is set, so the scalar default's struct + smem are byte-identical.
2058	#if SG_TUNED_DEC_DW_STAGE
2059	    if (kDecDwTransposeActive && dwt_base != nullptr) {
2060	        int64_t e = 0;
2061	        for (int s = 0; s < 9; ++s) {
2062	            DecDwSpec& sp = spec[s];
2063	            sp.t_off = e;
2064	            sp.dYt   = dwt_base + e;                                  // [Mpad, K]
2065	            sp.Xt    = dwt_base + e + dec_dw_mpad(sp.Nout) * sp.K;    // [Kin,  K]
2066	            e += dec_dw_weight_t_elems(sp.Nout, sp.Kin, sp.K);
2067	        }
2068	    } else {
2069	        for (int s = 0; s < 9; ++s) { spec[s].dYt = nullptr; spec[s].Xt = nullptr; spec[s].t_off = 0; }
2070	    }
2071	#else
2072	    (void)dwt_base;
2073	#endif
2074	}
2075	
2076	// ── CONTIGUOUS-TRANSPOSE PASS (SG_TUNED_DEC_DW_STAGE=1). Grid-cooperatively
2077	//    transpose each weight's dY[K,Nout] → dYt[Nout,K] and X[K,Kin] → Xt[Kin,K]
2078	//    into the packed dW-T scratch the specs bind. ELEMENT-OWNED (one writer per
2079	//    output element, fixed mapping) → DETERMINISTIC and A/A/A-safe; PURE bf16
2080	//    COPY (dYt[m,k]=dY[k,m] — NO arithmetic, NO reduction) → fp64-oracle parity
2081	//    is trivially preserved (the wgmma later consumes the SAME bf16 operand
2082	//    values in the SAME ascending-k order; only their MEMORY LAYOUT changed from
2083	//    transposed-strided gmem to K-contiguous gmem). Called by ALL CTAs after the
2084	//    backward writes dY/X to acts and BEFORE the dW phase, fenced by the existing
2085	//    B1 grid barrier (no new barrier). The total work is Σ_s (Nout_s+Kin_s)·K_s
2086	//    bf16 stores, touched ONCE per step and reused across every dW work item +
2087	//    split-K chunk of that weight. ──
2088	__device__ __forceinline__ void dectc_dw_transpose_operands(
2089	        const DecDwSpec spec[9], int cta, int nCTA) {
2090	#if SG_TUNED_DEC_DW_STAGE
2091	    if constexpr (!kDecDwTransposeActive) { (void)spec; (void)cta; (void)nCTA; return; }
2092	    const int tpb = blockDim.x;
2093	    const int64_t stride = (int64_t)nCTA * tpb;
2094	    const int64_t lane0  = (int64_t)cta * tpb + threadIdx.x;
2095	    for (int s = 0; s < 9; ++s) {
2096	        const DecDwSpec& sp = spec[s];
2097	        if (sp.dYt == nullptr) continue;
2098	        const int64_t K = sp.K, Nout = sp.Nout, Kin = sp.Kin;
2099	        const int64_t Mpad = dec_dw_mpad(sp.Nout);
2100	        // dYt[m,k] = dY[k,m] for m<Nout; pad rows [Nout,Mpad) = 0 (inert — the
2101	        // ring reads A rows unguarded, so the row dim is padded to a 64-atom
2102	        // boundary). Linear out-index i = m*K+k over the FULL padded [Mpad,K).
2103	        const int64_t ndy = Mpad * K;
2104	        for (int64_t i = lane0; i < ndy; i += stride) {
2105	            const int64_t m = i / K, k = i % K;
2106	            sp.dYt[i] = (m < Nout) ? sp.dY[k * Nout + m] : __float2bfloat16(0.f);
2107	        }
2108	        // Xt[n,k] = X[k,n], n in [0,Kin), k in [0,K). Linear out-index i = n*K+k.
2109	        // (No row pad: the ring guards B rows via row_valid → pad N-tile cols are
2110	        // zero-filled in smem, never read from Xt.)
2111	        const int64_t nx = Kin * K;
2112	        for (int64_t i = lane0; i < nx; i += stride) {
2113	            const int64_t n = i / K, k = i % K;
2114	            sp.Xt[i] = sp.X[k * Kin + n];
2115	        }
2116	    }
2117	#else
2118	    (void)spec; (void)cta; (void)nCTA;   // scalar default: no transpose pass
2119	#endif
2120	}
