2122	// ── dW M-atom INTERLEAVE group width (task #13 H3). A dW output "tile" (work
2123	//    item) owns a GROUP of up to kDecDwIL consecutive m64 atoms instead of one,
2124	//    so the engine runs kDecDwIL wgmmas/k-step into independent fragments sharing
2125	//    ONE staged X (B-operand) tile → the H1 win (overlap the MMAs + kDecDwIL× less
2126	//    X-operand HBM traffic) now applies to the dW K=T contraction (the post-H2
2127	//    dominant phase). kDecDwIL == the engine's interleave cap kDecMaxIL so the
2128	//    ring smem (DecTcSmem.sA, sized kDecAtomsPerSlot=min(kAtomsM,kDecMaxIL) A-tiles
2129	//    per slot) and the selftest-validated dW path (gemm_dw_kernel: MaxAtomsM=8,
2130	//    kIL=min(8,2)=2) match exactly. Ascending-k per atom is unchanged → numerics
2131	//    bit-identical + A/A/A determinism. Atoms-per-weight-N-tile / groups: ──
2132	constexpr int kDecDwIL = kDecMaxIL;
2133	__device__ __host__ __forceinline__ int dec_dw_atoms(int Nout)  { return (Nout + 63) / 64; }
2134	__device__ __host__ __forceinline__ int dec_dw_groups(int Nout) {
2135	    return (dec_dw_atoms(Nout) + kDecDwIL - 1) / kDecDwIL;
2136	}
