2454	// BUILD the per-vocab-row token lists (counting sort). Single CTA (caller guards
2455	// cta==0); runs in the P1 window so it overlaps fwd/bwd and the existing B1
2456	// barrier fences it before the P2 consume — NO new barrier. `row_start` is
2457	// [V+1] int32 (CSR offsets), `perm` is [T] int32 (token positions, ascending t
2458	// within each vocab-row bucket). All integer ops → bit-exact + deterministic.
2459	//
2460	// COST: O(T), PARALLEL over kW worker lanes (HBM-latency hidden) so the build is a
2461	// few hundred µs — far below the consume saving it enables. DETERMINISM via a fixed
2462	// STRUCTURAL decomposition: worker w owns the CONTIGUOUS t-chunk [w·C,(w+1)·C); it
2463	// histograms then scatters its chunk in ascending t into a per-(worker,row) slice
2464	// of perm whose base sits AFTER all lower-w workers' slices for the same row. Lower
2465	// w ⇒ lower t, and within a worker ascending t ⇒ each row's perm bucket is GLOBALLY
2466	// ascending t — the SAME order the old single-cursor scatter (and the old owner-scan
2467	// accumulation) produced, so bit-identical. All integer ops; no atomics on the hot
2468	// path. tok_ids is HBM int32 [T]. row_start is [V+1] (CSR offsets); perm is [T].
2469	__device__ __forceinline__ void dectc_embed_build_lists(
2470	        const int* __restrict__ tok_ids, int T,
2471	        int* __restrict__ row_start, int* __restrict__ perm) {
2472	    constexpr int kW = 64;                         // worker lanes (latency hiding)
2473	    __shared__ int wcnt[kW * dec::kVocab];         // per-(worker,row) count, then base cursor
2474	    // floor-balanced contiguous t-chunk per worker w: [c0(w), c0(w+1)).
2475	    auto c0 = [&] (int w) -> int { return (int)(((int64_t)w * T) / kW); };
2476	    // 1) zero the per-worker histograms (all threads).
2477	    for (int i = threadIdx.x; i < kW * dec::kVocab; i += blockDim.x) wcnt[i] = 0;
2478	    __syncthreads();
2479	    // 2) each of the first kW threads histograms its contiguous t-chunk into its own
2480	    //    row of wcnt (no atomics — private per worker).
2481	    if (threadIdx.x < kW) {
2482	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
2483	        int* my = wcnt + (int64_t)w * dec::kVocab;
2484	        for (int t = e0; t < e1; ++t) {
2485	            const int r = tok_ids[t];
2486	            if (r >= 0 && r < dec::kVocab) my[r]++;
2487	        }
2488	    }
2489	    __syncthreads();
2490	    // 3) exclusive prefix over r → row_start[V+1] (single thread; V tiny). totals[r]
2491	    //    = Σ_w wcnt[w][r]. row_start is exclusive over rows (CSR).
2492	    if (threadIdx.x == 0) {
2493	        int acc = 0;
2494	        for (int r = 0; r < dec::kVocab; ++r) {
2495	            row_start[r] = acc;
2496	            for (int w = 0; w < kW; ++w) acc += wcnt[(int64_t)w * dec::kVocab + r];
2497	        }
2498	        row_start[dec::kVocab] = acc;   // == #tokens with a valid row (≤ T)
2499	    }
2500	    __syncthreads();
2501	    // 4) per-(worker,row) base cursor: wcnt[w][r] ← row_start[r] + Σ_{w'<w} cnt[w'][r]
2502	    //    (ascending-worker prefix WITHIN a row → lower-t chunks land first). One
2503	    //    thread per row (V≤256 → fits blockDim) scans workers ascending.
2504	    if (threadIdx.x < dec::kVocab) {
2505	        const int r = threadIdx.x;
2506	        int base = row_start[r];
2507	        for (int w = 0; w < kW; ++w) {
2508	            int* slot = &wcnt[(int64_t)w * dec::kVocab + r];
2509	            const int c = *slot;
2510	            *slot = base;        // becomes the live append cursor for (w,r)
2511	            base += c;
2512	        }
2513	    }
2514	    __syncthreads();
2515	    // 5) scatter: each worker walks its chunk ascending t, appending t to perm at
2516	    //    its per-row cursor. Ascending t within the chunk + ascending-worker bases
2517	    //    ⇒ globally ascending t per row bucket.
2518	    if (threadIdx.x < kW) {
2519	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
2520	        int* cur = wcnt + (int64_t)w * dec::kVocab;
2521	        for (int t = e0; t < e1; ++t) {
2522	            const int r = tok_ids[t];
2523	            if (r >= 0 && r < dec::kVocab) perm[cur[r]++] = t;
2524	        }
2525	    }
2526	    __syncthreads();
2527	}
