2529	// CONSUME: assemble tok + pos embedding grads from the prebuilt lists. Flat grid-
2530	// stride over V·d (tok) and S·d (pos) output elements → all CTAs + threads busy,
2531	// coalesced dh0 reads, fixed ascending-t accumulation per row (deterministic).
2532	__device__ __forceinline__ void dectc_embed_owner_scan(
2533	        const DecActs& acts, const int* __restrict__ row_start,
2534	        const int* __restrict__ perm, int T,
2535	        float* __restrict__ grad, int cta, int nCTA) {
2536	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
2537	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
2538	    const __nv_bfloat16* __restrict__ dh0 = acts.dh0;
2539	    const int stride = nCTA * blockDim.x;
2540	    const int base   = cta * blockDim.x + threadIdx.x;
2541	    // ── tok grad: element (r,j) over V·d, grid-strided. Walk ONLY row r's tokens
2542	    //    (perm[row_start[r] .. row_start[r+1])) ascending → coalesced dh0 column
2543	    //    read across the warp (consecutive j on one token row). ──
2544	    const int64_t Vd = (int64_t)dec::kVocab * dec::kD;
2545	    for (int64_t e = base; e < Vd; e += stride) {
2546	        const int r = (int)(e / dec::kD);
2547	        const int j = (int)(e - (int64_t)r * dec::kD);
2548	        const int s0 = row_start[r], s1 = row_start[r + 1];
2549	        float accv = 0.0f;
2550	        for (int i = s0; i < s1; ++i)
2551	            accv += __bfloat162float(dh0[(int64_t)perm[i] * dec::kD + j]);
2552	        grad[tok_off + e] = accv;
2553	    }
2554	    // ── pos grad: element (p,j) over S·d, grid-strided. Tokens with (t%S)==p are
2555	    //    t = p, p+S, …, p+(B-1)·S (T=B·S) — closed-form ascending walk, no list. ──
2556	    const int64_t Sd = (int64_t)dec::kSeq * dec::kD;
2557	    const int B = T / dec::kSeq;
2558	    for (int64_t e = base; e < Sd; e += stride) {
2559	        const int p = (int)(e / dec::kD);
2560	        const int j = (int)(e - (int64_t)p * dec::kD);
2561	        float accv = 0.0f;
2562	        int t = p;
2563	        for (int i = 0; i < B; ++i, t += dec::kSeq)
2564	            accv += __bfloat162float(dh0[(int64_t)t * dec::kD + j]);
2565	        grad[pos_off + e] = accv;
2566	    }
2567	}
