2570	//  P2 — LN-vector grad reduce. The 10 γ/β grads were accumulated tile-locally
2571	//    into each CTA's lnvec partials [kNumLnVec × d]; sum across CTAs in
2572	//    ASCENDING CTA index (deterministic) into the 10 dec_layout slots of grad.
2573	//    `lnvec_base` is the start of the [nCTA × kLnVecElems] partial region.
2574	// ════════════════════════════════════════════════════════════════════════
2575	__device__ __forceinline__ void dectc_lnvec_reduce(
2576	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
2577	        int nCTA, int cta) {
2578	    // Each CTA reduces a subset of the 10 LN tensors (round-robin by tensor).
2579	    for (int v = cta; v < kNumLnVec; v += nCTA) {
2580	        const int goff = kLnVecTensorIdx[v];
2581	        const int64_t gbase = kDecOffsets[goff];
2582	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
2583	            float accv = 0.0f;
2584	            for (int c = 0; c < nCTA; ++c)
2585	                accv += lnvec_base[(int64_t)c * kLnVecElems + (int64_t)v * dec::kD + j];
2586	            grad[gbase + j] = accv;
2587	        }
2588	    }
2589	}
